  return {
    results: scenario.steps.map((step) => {
      const base = (step as QuoteStep).items.length * SWORD_BASE_PREMIUM;
      return {
        premium: Math.ceil(base * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE),
      };
    }),
  };
}

